    assert_eq!(ok2.status.code(), Some(0), "{:?}", ok2.stderr);
    assert_eq!(ok2.stdout, ok.stdout);

    // A record file whose content differs by one byte must fail.
    let wrong = dir.write(b"wrong-\xff.bin", b"\xff\xfebinarX");
